  if (pin && fob && locked) { locked = false; pinAt = 0; fobAt = 0; show("PIN + fob OK"); bt.println("UNLOCKED"); Serial.println("UNLOCKED"); }
}

void setup() {
  servo.attach(SERVO_PIN);
  Serial.begin(9600);
  bt.begin(9600);
  lcdBegin();
  radioBegin();
  show("PIN + fob needed");
}

void loop() {
  if (btPoll()) {
    btCmd.toUpperCase();
    if (btCmd.startsWith("PIN ")) {
      if (btCmd.substring(4) == PIN_CODE) { pinAt = millis(); bt.println("PIN accepted - waiting for the fob"); show("PIN ok, need fob"); }
      else { bt.println("WRONG PIN"); show("wrong PIN"); }
      tryUnlock();
    } else if (btCmd == "LOCK") { locked = true; show("locked again"); bt.println("LOCKED"); }
  }
  if (recvText()) {                                          // fob packet: K<counter>:<code>
    int colon = rxText.indexOf(':');
    unsigned long n = rxText.substring(1, colon).toInt();
    unsigned long code = rxText.substring(colon + 1).toInt();
    if (n > lastCounter && n <= lastCounter + 5 && code == codeFor(n)) { lastCounter = n; fobAt = millis(); Serial.println("fob code accepted (counter " + String(n) + ")"); show("fob ok"); tryUnlock(); }
    else { Serial.println("REJECTED fob code (replay or wrong code)"); bt.println("ALERT: fob replay rejected"); show("replay blocked"); }
  }
}

