void lcdBegin() { lcd.init(); lcd.backlight(); }

bool on = false;
unsigned long irUntil = 0;

void apply(String who) {
  digitalWrite(RELAY_PIN, on ? RELAY_ON : RELAY_OFF);
  digitalWrite(GREEN_LED, on);
  digitalWrite(RED_LED, millis() < irUntil);
  lcdRow(0, String("Appliance ") + (on ? "ON" : "OFF"));
