#define KEEP 10
int logT[KEEP], logH[KEEP];
unsigned long logTime[KEEP];
int n = 0;
unsigned long last = 0;

void sendLine(int i) {
  bt.println("LOG," + String(logTime[i]) + "," + String(logT[i]) + "," + String(logH[i]));
