  pinMode(BTN1, INPUT_PULLUP);
  Serial.begin(9600);
  bt.begin(9600);
  dht.begin();
  bt.println("logger ready: DUMP, CLEAR");
}

void loop() {
  if (millis() - last >= 5000) {
    last = millis();
    if (n == KEEP) { for (int i = 1; i < KEEP; i++) { logT[i - 1] = logT[i]; logH[i - 1] = logH[i]; logTime[i - 1] = logTime[i]; } n = KEEP - 1; }
    logT[n] = dht.readTemperature(); logH[n] = dht.readHumidity(); logTime[n] = millis() / 1000;
