void enqueue(int act, int src) {
  if (qLen >= QMAX) { Serial.println("queue full - dropped"); return; }
  qAct[qLen] = act; qSrc[qLen] = src; qLen++;
}

String actionName(int a) { if (a == 1) return "LIGHT ON"; if (a == 2) return "LIGHT OFF"; if (a == 3) return "LIGHT BLINK"; return "UNKNOWN"; }

