  if (btPoll()) { btCmd.toUpperCase(); if (btCmd.startsWith("ACT ")) enqueue(btCmd.substring(4).toInt(), 1); }
  if (recvText() && rxText.startsWith("ACT ")) enqueue(rxText.substring(4).toInt(), 2);
  if (qLen > 0) {
    Serial.println("[" + srcName(qSrc[0]) + "] " + actionName(qAct[0]));
    bt.println("did " + actionName(qAct[0]));
    for (int i = 1; i < qLen; i++) { qAct[i - 1] = qAct[i]; qSrc[i - 1] = qSrc[i]; }
