String hex2(int v) {                        // two hex digits
  String h = "0123456789ABCDEF";
  return String(h.charAt((v >> 4) & 15)) + String(h.charAt(v & 15));
}
int unhex(char c) { if (c >= '0' && c <= '9') return c - '0'; if (c >= 'A' && c <= 'F') return c - 'A' + 10; return 0; }

#define KEY 0x5A
int idx = 0;

String message(int i) { if (i == 0) return "HELLO"; if (i == 1) return "OPEN DOOR"; return "SENSOR OK"; }

String encrypt(String plain) {
  String out = "";
  for (int i = 0; i < plain.length(); i++) out += hex2(plain.charAt(i) ^ KEY);
  return out;
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  Serial.begin(9600);
  radioBegin();
  lcdBegin();
  lcdRow(0, "press the button");
  lcdRow(1, "to send a msg");
}

void loop() {
  if (pressed()) {
    String plain = message(idx);
    String cipher = encrypt(plain);
    bool ok = sendText(cipher);
    lcdRow(0, plain);
    lcdRow(1, cipher.substring(0, 16));
    Serial.println("sent '" + plain + "' as " + cipher + (ok ? "" : " (lost)"));
    idx = (idx + 1) % 3;
  }
}

