unsigned long bound[3] = {0, 0, 0};
int learning = -1;                                 // action being learned, -1 = none
int pick = -1;                                     // last action chosen with the button (the next press moves on)
bool relayOn = false;
int macro[8];
int macroLen = 0;
bool recording = false;

String actionName(int a) { if (a == 0) return "relay toggle"; if (a == 1) return "servo 0"; return "servo 180"; }

void run(int a) {
  if (a == 0) { relayOn = !relayOn; digitalWrite(RELAY_PIN, relayOn ? RELAY_ON : RELAY_OFF); }
  if (a == 1) servo.write(0);
  if (a == 2) servo.write(180);
  lcdRow(0, "Action:");
  lcdRow(1, actionName(a));
  Serial.println("run " + actionName(a));
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  digitalWrite(RELAY_PIN, RELAY_OFF);
  pinMode(RELAY_PIN, OUTPUT);
  servo.attach(SERVO_PIN);
  servo.write(90);
  Serial.begin(9600);
  bt.begin(9600);
  irrecv.enableIRIn();
  lcdBegin();
  lcdRow(0, "Remote hub");
  lcdRow(1, "button = learn");
}

void loop() {
  if (pressed()) {
    pick = (pick + 1) % 3;
    learning = pick;
    lcdRow(0, "Learning:");
    lcdRow(1, actionName(learning) + "?");
    Serial.println("press a remote key for: " + actionName(learning));
  }
  if (irrecv.decode(&ir)) {
    if (learning >= 0) { bound[learning] = ir.value; Serial.println("learned 0x" + String(ir.value, HEX) + " = " + actionName(learning)); lcdRow(0, "Learned!"); lcdRow(1, actionName(learning)); learning = -1; }
    else for (int a = 0; a < 3; a++) if (bound[a] == ir.value) run(a);
    irrecv.resume();
  }
  if (btPoll()) {
    btCmd.toUpperCase();
    if (btCmd == "REC") { recording = true; macroLen = 0; bt.println("recording"); }
    else if (btCmd == "END") { recording = false; bt.println("macro saved: " + String(macroLen) + " steps"); }
    else if (btCmd == "PLAY") { bt.println("playing"); for (int i = 0; i < macroLen; i++) { run(macro[i]); delay(1000); } bt.println("done"); }
    else {
      int a = btCmd == "RELAY" ? 0 : (btCmd == "SERVO0" ? 1 : (btCmd == "SERVO180" ? 2 : -1));
      if (a >= 0) { if (recording && macroLen < 8) { macro[macroLen] = a; macroLen++; bt.println("step " + String(macroLen)); } else run(a); }
    }
  }
}

