#include <Wire.h>
#include <LiquidCrystal_I2C.h>
LiquidCrystal_I2C lcd(0x27, 16, 2);

void lcdRow(int row, String s) {           // write one full 16-character row (pads with spaces)
  while (s.length() < 16) s += " ";
  lcd.setCursor(0, row);
  lcd.print(s);
}
void lcdBegin() { lcd.init(); lcd.backlight(); }
#include <SoftwareSerial.h>
SoftwareSerial link(LINK_RX, LINK_TX);
String linkBuf = "", linkLine = "";
bool linkPoll() {                          // true when a whole line has arrived from the other board (in linkLine)
  while (link.available() > 0) {
    char c = link.read();
    if (c == '\r') continue;
    if (c == '\n') { linkLine = linkBuf; linkBuf = ""; return linkLine.length() > 0; }
    linkBuf += c;
  }
  return false;
}

int passed = 0, total = 0;
String failed = "";

void report(String name, bool ok) {
  total++;
  if (ok) passed++; else failed += name + " ";
  lcdRow(0, "Test " + String(total) + ": " + name);
  lcdRow(1, ok ? "PASS" : "FAIL");
  Serial.println(name + (ok ? ": PASS" : ": FAIL"));
  delay(700);
}

void setup() {
  digitalWrite(RELAY_PIN, RELAY_OFF);
  pinMode(RELAY_PIN, OUTPUT);
  Serial.begin(9600);
  bt.begin(9600);
  link.begin(9600);
  irrecv.enableIRIn();
  lcdBegin();
  radioBegin();
  Serial.println("=== wireless self-test ===");
  lcdRow(0, "Self-test"); lcdRow(1, "starting..."); delay(800);

  bt.println("AT");                                               // 1: HC-05 answers OK to AT
  bool btOk = false;
  unsigned long t0 = millis();
  while (millis() - t0 < 1200 && !btOk) { delay(20); if (btPoll() && btCmd == "OK") btOk = true; }
  report("HC-05", btOk);

  bool radioOk = false;                                           // 2: radio round trip: TEST -> ECHO TEST
  for (int tries = 0; tries < 3 && !radioOk; tries++) {
    if (sendText("TEST")) {
      t0 = millis();
      while (millis() - t0 < 600 && !radioOk) { if (recvText() && rxText == "ECHO TEST") radioOk = true; }
    }
  }
  report("nRF24", radioOk);

  link.println("LINK?");                                          // 3: serial link through the level converter
  bool linkOk = false;
  t0 = millis();
  while (millis() - t0 < 1200 && !linkOk) { delay(20); if (linkPoll() && linkLine == "LINK OK") linkOk = true; }
  report("NodeMCU link", linkOk);

  lcdRow(0, "Test 4: IR"); lcdRow(1, "press a key...");        // 4: IR receiver needs a key press
  bool irOk = false;
  t0 = millis();
  while (millis() - t0 < 8000 && !irOk) { delay(20); if (irrecv.decode(&ir)) { irOk = true; irrecv.resume(); } }
  report("IR", irOk);

  digitalWrite(RELAY_PIN, RELAY_ON); delay(400); digitalWrite(RELAY_PIN, RELAY_OFF);       // 5: relay click (listen for it)
  report("relay click", true);
  Serial.println("RESULT: " + String(passed) + "/" + String(total) + (passed == total ? " PASS" : " FAIL"));
  if (passed != total) Serial.println("failed: " + failed);
}

void loop() {
  lcdRow(0, passed == total ? "SELF-TEST PASS" : "SELF-TEST FAIL");
  lcdRow(1, String(passed) + "/" + String(total) + (passed == total ? " ok" : " " + failed));
  delay(1000);
}

